using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration ---------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools -----------------------------------------------------------------
var notepad = new Notepad();
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(notepad.SaveNote),
    AIFunctionFactory.Create(notepad.ReadNotes),
};

// --- Agent setup -----------------------------------------------------------
IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web for relevant information using the web_search tool.
           Perform multiple searches with varied queries to get broad coverage.
        2. Save important findings as notes using the save_note tool.
        3. After gathering enough information, read all notes with read_notes
           and produce a well-structured summary with key findings and sources.
        Always cite sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run -------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (type 'exit')       ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var session = await agent.CreateSessionAsync(
    conversationId: Guid.NewGuid().ToString());

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Clear();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching…\n");
    Console.ResetColor();

    await foreach (var update in agent.RunStreamingAsync(
        topic, session, runOptions))
    {
        foreach (var part in update.ContentUpdate)
        {
            Console.Write(part.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ===========================================================================
// Tool implementations
// ===========================================================================

/// <summary>Simulated web search tool using DuckDuckGo Lite.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    [Description("Search the web for a query and return a list of result snippets with URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var results = ParseDuckDuckGoResults(html, maxResults);

            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}\n");
            for (var i = 0; i < results.Count; i++)
            {
                var (title, snippet, link) = results[i];
                sb.AppendLine($"{i + 1}. {title}");
                sb.AppendLine($"   {snippet}");
                sb.AppendLine($"   Source: {link}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Url)> ParseDuckDuckGoResults(
        string html, int max)
    {
        var results = new List<(string, string, string)>();

        // DuckDuckGo Lite returns a simple HTML table with results.
        // Each result link is in an <a> tag with class "result-link".
        var remaining = html.AsSpan();
        while (results.Count < max)
        {
            var linkIdx = remaining.IndexOf("class=\"result-link\"");
            if (linkIdx < 0)
                break;

            remaining = remaining[linkIdx..];

            // Extract href
            var hrefIdx = remaining.IndexOf("href=\"");
            if (hrefIdx < 0) break;
            remaining = remaining[(hrefIdx + 6)..];
            var hrefEnd = remaining.IndexOf('"');
            if (hrefEnd < 0) break;
            var href = remaining[..hrefEnd].ToString();
            remaining = remaining[hrefEnd..];

            // Extract link text (title)
            var gtIdx = remaining.IndexOf('>');
            if (gtIdx < 0) break;
            remaining = remaining[(gtIdx + 1)..];
            var ltIdx = remaining.IndexOf('<');
            if (ltIdx < 0) break;
            var title = WebUtility.HtmlDecode(remaining[..ltIdx].ToString().Trim());
            remaining = remaining[ltIdx..];

            // Extract snippet — look for the next "result-snippet" class
            var snippetIdx = remaining.IndexOf("class=\"result-snippet\"");
            var snippet = "";
            if (snippetIdx >= 0 && snippetIdx < 2000)
            {
                var snipSpan = remaining[snippetIdx..];
                var snipGt = snipSpan.IndexOf('>');
                if (snipGt >= 0)
                {
                    snipSpan = snipSpan[(snipGt + 1)..];
                    var snipLt = snipSpan.IndexOf('<');
                    if (snipLt >= 0)
                        snippet = WebUtility.HtmlDecode(snipSpan[..snipLt].ToString().Trim());
                }
            }

            if (!string.IsNullOrWhiteSpace(title) && !string.IsNullOrWhiteSpace(href))
                results.Add((title, snippet, href));
        }

        return results;
    }
}

/// <summary>Note-taking tool that stores findings in memory.</summary>
sealed class Notepad
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a research note. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content with source attribution")] string content)
    {
        _notes.Add((title, content));
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Read all saved research notes.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");
        for (var i = 0; i < _notes.Count; i++)
        {
            var (title, content) = _notes[i];
            sb.AppendLine($"--- Note {i + 1}: {title} ---");
            sb.AppendLine(content);
            sb.AppendLine();
        }

        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

